"""Configuration loading and validation.

A configuration is a YAML mapping with two keys::

    sources:
      - id: <unique string>
        type: jsonl
        path: <path to a JSON Lines file>
        batch_size: <positive integer>
        transforms:           # optional, source-level; run after the
          - op: ...           # shared top-level transforms
    transforms:
      - op: rename | drop | set | cast
        ...

Only these keys are recognised; anything else is a ConfigurationError so a
typo cannot silently change behaviour.
"""

import hashlib
import json
import os

from . import yaml_lite
from .errors import ConfigurationError

CAST_TYPES = ("string", "integer", "number", "boolean")
SUPPORTED_SOURCE_TYPES = ("jsonl",)
TRANSFORM_OPS = ("rename", "drop", "set", "cast")
TOP_LEVEL_KEYS = ("sources", "transforms")
SOURCE_REQUIRED_KEYS = ("id", "type", "path", "batch_size")
SOURCE_KEYS = SOURCE_REQUIRED_KEYS + ("transforms",)


def split_path(path):
    """Split a dotted field path into non-empty segments."""
    if not isinstance(path, str) or path == "":
        raise ConfigurationError("field path must be a non-empty string")
    if path.startswith(".") or path.endswith(".") or ".." in path:
        raise ConfigurationError("illegal field path %r" % path)
    parts = path.split(".")
    if any(part == "" or part != part.strip() for part in parts):
        raise ConfigurationError("illegal field path %r" % path)
    return parts


def _require_mapping(value, what):
    if not isinstance(value, dict):
        raise ConfigurationError("%s must be a mapping" % what)


def _validate_transform(raw, index, prefix="transforms"):
    where = "%s[%d]" % (prefix, index)
    if not isinstance(raw, dict):
        raise ConfigurationError("%s must be a mapping" % where)
    if "op" not in raw:
        raise ConfigurationError("%s is missing 'op'" % where)
    op = raw["op"]
    if not isinstance(op, str) or op not in TRANSFORM_OPS:
        raise ConfigurationError(
            "%s has unknown operation %r (expected one of %s)"
            % (where, op, ", ".join(TRANSFORM_OPS))
        )
    allowed = {"op": None}
    if op == "rename":
        allowed.update({"from": None, "to": None})
        for key in ("from", "to"):
            if key not in raw:
                raise ConfigurationError("%s (%s) requires %r" % (where, op, key))
            split_path(raw[key])
    elif op in ("drop", "cast", "set"):
        allowed["field"] = None
        if "field" not in raw:
            raise ConfigurationError("%s (%s) requires 'field'" % (where, op))
        split_path(raw["field"])
        if op == "cast":
            allowed["type"] = None
            if "type" not in raw:
                raise ConfigurationError("%s (cast) requires 'type'" % where)
            if raw["type"] not in CAST_TYPES:
                raise ConfigurationError(
                    "%s (cast) accepts only %s, got %r"
                    % (where, ", ".join(CAST_TYPES), raw["type"])
                )
        elif op == "set":
            allowed["value"] = None
            if "value" not in raw:
                raise ConfigurationError("%s (set) requires 'value'" % where)
            value = raw["value"]
            if isinstance(value, (dict, list)):
                raise ConfigurationError(
                    "%s (set) value must be a scalar" % where
                )
    extra = set(raw) - set(allowed)
    if extra:
        raise ConfigurationError(
            "%s (%s) has unknown keys: %s" % (where, op, ", ".join(sorted(extra)))
        )
    # Return a plain ordered dict preserving configuration key order; the
    # fingerprint is sensitive to that order.
    return {k: raw[k] for k in raw}


def _validate_source(raw, index, seen_ids):
    where = "sources[%d]" % index
    if not isinstance(raw, dict):
        raise ConfigurationError("%s must be a mapping" % where)
    missing = [k for k in SOURCE_REQUIRED_KEYS if k not in raw]
    if missing:
        raise ConfigurationError(
            "%s is incomplete, missing: %s" % (where, ", ".join(missing))
        )
    extra = set(raw) - set(SOURCE_KEYS)
    if extra:
        raise ConfigurationError(
            "%s has unknown keys: %s" % (where, ", ".join(sorted(extra)))
        )
    sid, stype, path, batch = (raw[k] for k in SOURCE_REQUIRED_KEYS)
    if not isinstance(sid, str) or sid == "":
        raise ConfigurationError("%s.id must be a non-empty string" % where)
    if sid in seen_ids:
        raise ConfigurationError("duplicate source id %r" % sid)
    if stype not in SUPPORTED_SOURCE_TYPES:
        raise ConfigurationError(
            "%s has unsupported type %r (expected jsonl)" % (where, stype)
        )
    if not isinstance(path, str) or path == "":
        raise ConfigurationError("%s.path must be a non-empty string" % where)
    if isinstance(batch, bool) or not isinstance(batch, int) or batch < 1:
        raise ConfigurationError(
            "%s.batch_size must be a positive integer" % where
        )
    raw_transforms = raw.get("transforms", [])
    if not isinstance(raw_transforms, list):
        raise ConfigurationError("%s.transforms must be a list" % where)
    prefix = "%s.transforms" % where
    transforms = [
        _validate_transform(item, i, prefix)
        for i, item in enumerate(raw_transforms)
    ]
    seen_ids.add(sid)
    return {
        "id": sid,
        "type": stype,
        "path": path,
        "batch_size": batch,
        "transforms": transforms,
    }


class Config:
    def __init__(self, sources, transforms, raw):
        self.sources = sources
        self.transforms = transforms
        self.raw = raw

    def fingerprint(self):
        """Stable hash of the configuration; embedded in the checkpoint."""
        spec = {"sources": self.sources, "transforms": self.transforms}
        blob = json.dumps(spec, ensure_ascii=False, separators=(",", ":"))
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()


def _parse_document(text):
    try:
        doc = yaml_lite.loads(text)
    except yaml_lite.YAMLError as exc:
        raise ConfigurationError(str(exc))
    if doc is None:
        raise ConfigurationError("configuration is empty")
    if not isinstance(doc, dict):
        raise ConfigurationError("top-level configuration must be a mapping")
    return doc


def build_config(doc):
    extra = set(doc) - set(TOP_LEVEL_KEYS)
    if extra:
        raise ConfigurationError(
            "unknown configuration keys: %s" % ", ".join(sorted(extra))
        )
    if "sources" not in doc:
        raise ConfigurationError("configuration is missing 'sources'")
    raw_sources = doc["sources"]
    if not isinstance(raw_sources, list) or not raw_sources:
        raise ConfigurationError("'sources' must be a non-empty list")
    seen = set()
    sources = [
        _validate_source(item, i, seen) for i, item in enumerate(raw_sources)
    ]
    transforms = []
    raw_transforms = doc.get("transforms", [])
    if not isinstance(raw_transforms, list):
        raise ConfigurationError("'transforms' must be a list")
    for i, item in enumerate(raw_transforms):
        transforms.append(_validate_transform(item, i))
    return Config(sources, transforms, doc)


def load_config(path):
    """Read, parse and validate a configuration file."""
    try:
        with open(path, "r", encoding="utf-8") as fp:
            text = fp.read()
    except OSError as exc:
        raise ConfigurationError("cannot read %s: %s" % (path, exc))
    return build_config(_parse_document(text))


def parse_config_text(text):
    """Build a Config from YAML text (used by tests and embedding)."""
    return build_config(_parse_document(text))


def abspath(path):
    """Normalise a CLI path for checkpoint identity checks."""
    return os.path.abspath(path)

"""The ETL engine: run, replay, transforms, schema evolution, checkpoints.

For every input JSON object the engine reads ``source_id`` / ``event_id`` /
``payload``, applies the configured transforms to the payload in order, and
emits one output object::

    {"source_id": ..., "event_id": ..., "schema_version": N, "data": {...}}

Sources are processed in configuration order. Every ``batch_size`` records
for a source (and at each source boundary) the output is fsynced and the
checkpoint is atomically replaced. Replay truncates any uncommitted tail of
the output using the byte offset stored in the checkpoint, then continues, so
records are never duplicated or skipped.
"""

import json
import os
import tempfile

from .config import split_path
from .errors import (
    CheckpointError,
    DataValidationError,
    SinkError,
    SourceError,
)

CHECKPOINT_VERSION = 1
ENCODING = "utf-8"


# --------------------------------------------------------------------------
# Field path helpers
# --------------------------------------------------------------------------


def _desc(parts):
    return ".".join(parts)


def _walk(data, parts, where):
    """Walk a path that must exist through nested dicts."""
    cur = data
    for part in parts:
        if not isinstance(cur, dict) or part not in cur:
            raise DataValidationError("%s: path %r does not exist"
                                      % (where, _desc(parts)))
        cur = cur[part]
    return cur


def _parent_existing(data, parts, where):
    """Parent container must exist; leaf key returned (leaf may be absent)."""
    parent = _walk(data, parts[:-1], where)
    if not isinstance(parent, dict):
        raise DataValidationError("%s: path %r does not exist"
                                  % (where, _desc(parts)))
    return parent, parts[-1]


def _parent_and_key(data, parts, where):
    """Parent container and leaf must both exist (drop/cast/rename-from)."""
    parent, key = _parent_existing(data, parts, where)
    if key not in parent:
        raise DataValidationError("%s: path %r does not exist"
                                  % (where, _desc(parts)))
    return parent, key


# --------------------------------------------------------------------------
# Casts
# --------------------------------------------------------------------------


def _cast_integer(value, where):
    if isinstance(value, bool) or value is None:
        raise DataValidationError("%s: cannot cast %r to integer" % (where, value))
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if value.is_integer():
            return int(value)
        raise DataValidationError("%s: cannot cast %r to integer" % (where, value))
    if isinstance(value, str):
        text = value.strip()
        body = text[1:] if text[:1] in ("+", "-") else text
        if body.isdigit():
            return int(text)
    raise DataValidationError("%s: cannot cast %r to integer" % (where, value))


def _finite_float(text, where, value):
    try:
        result = float(text)
    except ValueError:
        result = None
    if result is None or result != result or result in (
        float("inf"),
        float("-inf"),
    ):
        raise DataValidationError("%s: cannot cast %r to number" % (where, value))
    return result


def _cast_number(value, where):
    if isinstance(value, bool) or value is None:
        raise DataValidationError("%s: cannot cast %r to number" % (where, value))
    if isinstance(value, int):
        return float(value)
    if isinstance(value, float):
        return _finite_float(value, where, value)
    if isinstance(value, str):
        return _finite_float(value.strip(), where, value)
    raise DataValidationError("%s: cannot cast %r to number" % (where, value))


def _cast_boolean(value, where):
    if isinstance(value, bool):
        return value
    if value is None:
        raise DataValidationError("%s: cannot cast null to boolean" % where)
    if isinstance(value, str):
        low = value.strip()
        if low == "true":
            return True
        if low == "false":
            return False
    elif isinstance(value, int) and value in (0, 1):
        return bool(value)
    elif isinstance(value, float) and value in (0.0, 1.0):
        return bool(value)
    raise DataValidationError("%s: cannot cast %r to boolean" % (where, value))


def _cast_string(value, where):
    if value is None or isinstance(value, (dict, list)):
        raise DataValidationError("%s: cannot cast %r to string" % (where, value))
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "true" if value else "false"
    return json.dumps(value)


def _cast_value(value, target, where):
    if target == "string":
        return _cast_string(value, where)
    if target == "integer":
        return _cast_integer(value, where)
    if target == "number":
        return _cast_number(value, where)
    return _cast_boolean(value, where)


# --------------------------------------------------------------------------
# Transforms
# --------------------------------------------------------------------------


def apply_transforms(data, transforms, where):
    """Apply transforms in order to ``data`` (mutated in place)."""
    for raw in transforms:
        op = raw["op"]
        if op == "rename":
            parts_from = split_path(raw["from"])
            parts_to = split_path(raw["to"])
            value = _walk(data, parts_from, where)
            dest_parent, dest_key = _parent_existing(data, parts_to, where)
            if dest_key in dest_parent:
                # renaming over an existing field would silently lose data
                raise DataValidationError(
                    "%s: rename destination %r already exists"
                    % (where, _desc(parts_to))
                )
            src_parent, src_key = _parent_and_key(data, parts_from, where)
            del src_parent[src_key]
            dest_parent[dest_key] = value
        elif op == "drop":
            parts = split_path(raw["field"])
            parent, key = _parent_and_key(data, parts, where)
            del parent[key]
        elif op == "set":
            parts = split_path(raw["field"])
            parent, key = _parent_existing(data, parts, where)
            parent[key] = raw["value"]
        else:  # cast
            parts = split_path(raw["field"])
            parent, key = _parent_and_key(data, parts, where)
            parent[key] = _cast_value(parent[key], raw["type"], where + " (cast)")
    return data


# --------------------------------------------------------------------------
# Structural schema fingerprint
# --------------------------------------------------------------------------


def _schema_shape(value):
    """Type/structure descriptor independent of concrete leaf values.

    Dicts contribute their key set and each value's shape; arrays contribute
    the distinct shapes of their elements (order- and multiplicity-free, so
    growing an array does not look like a schema change, but a new kind of
    nested object inside one does).
    """
    if isinstance(value, dict):
        return {"dict": {k: _schema_shape(value[k]) for k in value}}
    if isinstance(value, list):
        shapes = {
            json.dumps(_schema_shape(v), sort_keys=True, separators=(",", ":"))
            for v in value
        }
        return {"list": sorted(shapes)}
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "number"
    return "string"


def schema_fingerprint(value):
    return json.dumps(_schema_shape(value), ensure_ascii=False,
                      sort_keys=True, separators=(",", ":"))


# --------------------------------------------------------------------------
# Per-source state and checkpoint (de)serialisation
# --------------------------------------------------------------------------


class SourceState:
    def __init__(self, spec):
        self.spec = spec
        self.offset = 0
        self.records = 0
        self.schema_version = 0
        self.schema_fingerprint = None

    def note_schema(self, fp):
        if fp != self.schema_fingerprint:
            self.schema_version += 1
            self.schema_fingerprint = fp

    def to_json(self):
        return {
            "path": self.spec["path"],
            "offset": self.offset,
            "records": self.records,
            "schema_version": self.schema_version,
            "schema_fingerprint": self.schema_fingerprint,
        }

    @classmethod
    def from_json(cls, spec, raw):
        state = cls(spec)
        if not isinstance(raw, dict):
            raise CheckpointError("checkpoint entry for source %r is invalid"
                                  % spec["id"])
        required = ("path", "offset", "records", "schema_version",
                    "schema_fingerprint")
        for key in required:
            if key not in raw:
                raise CheckpointError(
                    "checkpoint entry for source %r is missing %r"
                    % (spec["id"], key)
                )
        if raw["path"] != spec["path"]:
            raise CheckpointError(
                "source %r path differs from the one in the checkpoint"
                % spec["id"]
            )
        for key in ("offset", "records", "schema_version"):
            val = raw[key]
            if isinstance(val, bool) or not isinstance(val, int) or val < 0:
                raise CheckpointError(
                    "checkpoint %s for source %r is invalid"
                    % (key, spec["id"])
                )
        fp = raw["schema_fingerprint"]
        if fp is not None and not isinstance(fp, str):
            raise CheckpointError(
                "checkpoint schema_fingerprint for source %r is invalid"
                % spec["id"]
            )
        state.offset = raw["offset"]
        state.records = raw["records"]
        state.schema_version = raw["schema_version"]
        state.schema_fingerprint = fp
        return state


class Checkpoint:
    def __init__(self, config, states, sink_offset):
        self.config = config
        self.states = states
        self.sink_offset = sink_offset

    def to_json(self):
        return {
            "version": CHECKPOINT_VERSION,
            "config_fingerprint": self.config.fingerprint(),
            "sink_offset": self.sink_offset,
            "sources": {
                spec["id"]: state.to_json()
                for spec, state in zip(self.config.sources, self.states)
            },
        }

    def write_atomic(self, path):
        directory = os.path.dirname(os.path.abspath(path)) or "."
        tmp = None
        try:
            fd, tmp = tempfile.mkstemp(
                prefix=".stream-etl-cp-", suffix=".tmp", dir=directory
            )
            with os.fdopen(fd, "wb") as fp:
                fp.write((json.dumps(self.to_json(), ensure_ascii=False)
                          + "\n").encode(ENCODING))
                fp.flush()
                os.fsync(fp.fileno())
            os.replace(tmp, path)
            tmp = None
            try:
                dir_fd = os.open(directory, os.O_RDONLY)
                try:
                    os.fsync(dir_fd)
                finally:
                    os.close(dir_fd)
            except OSError:
                pass
        except OSError as exc:
            raise SinkError("cannot write checkpoint %s: %s" % (path, exc))
        finally:
            if tmp is not None:
                try:
                    os.unlink(tmp)
                except OSError:
                    pass


def load_checkpoint(path, config):
    try:
        with open(path, "rb") as fp:
            raw = fp.read()
    except OSError as exc:
        raise CheckpointError("cannot read checkpoint %s: %s" % (path, exc))
    try:
        doc = json.loads(raw.decode(ENCODING))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise CheckpointError("checkpoint %s is corrupt" % path)
    if not isinstance(doc, dict):
        raise CheckpointError("checkpoint %s is corrupt" % path)
    if doc.get("version") != CHECKPOINT_VERSION:
        raise CheckpointError("checkpoint version mismatch (expected %d, got %r)"
                              % (CHECKPOINT_VERSION, doc.get("version")))
    if doc.get("config_fingerprint") != config.fingerprint():
        raise CheckpointError("checkpoint was written by a different configuration")
    sink_offset = doc.get("sink_offset")
    if (isinstance(sink_offset, bool) or not isinstance(sink_offset, int)
            or sink_offset < 0):
        raise CheckpointError("checkpoint sink_offset is invalid")
    raw_sources = doc.get("sources")
    if not isinstance(raw_sources, dict):
        raise CheckpointError("checkpoint sources section is invalid")
    by_id = {spec["id"]: spec for spec in config.sources}
    if set(raw_sources) != set(by_id):
        raise CheckpointError("checkpoint sources do not match configuration")
    states = [
        SourceState.from_json(by_id[spec["id"]], raw_sources[spec["id"]])
        for spec in config.sources
    ]
    return Checkpoint(config, states, sink_offset)


# --------------------------------------------------------------------------
# Filesystem preflight
# --------------------------------------------------------------------------


def _guard_paths(config, output_path, checkpoint_path):
    out_abs = os.path.abspath(output_path)
    cp_abs = os.path.abspath(checkpoint_path)
    if out_abs == cp_abs:
        from .errors import ConfigurationError
        raise ConfigurationError("output and checkpoint paths must differ")
    input_abs = {os.path.abspath(spec["path"]) for spec in config.sources}
    if out_abs in input_abs:
        from .errors import ConfigurationError
        raise ConfigurationError(
            "output path %s must not be an input file" % output_path
        )
    if cp_abs in input_abs:
        from .errors import ConfigurationError
        raise ConfigurationError(
            "checkpoint path %s must not be an input file" % checkpoint_path
        )


def _ensure_inputs_readable(config):
    for spec in config.sources:
        path = spec["path"]
        if not os.path.exists(path):
            raise SourceError("input %s does not exist" % path)
        if not os.path.isfile(path):
            raise SourceError("input %s is not a regular file" % path)
        if not os.access(path, os.R_OK):
            raise SourceError("input %s is not readable" % path)


def _open_sink_for_run(path):
    parent = os.path.dirname(os.path.abspath(path)) or "."
    if not os.path.isdir(parent):
        raise SinkError("output directory %s does not exist" % parent)
    try:
        return open(path, "xb")
    except FileExistsError:
        from .errors import ConfigurationError
        raise ConfigurationError(
            "output %s already exists; run requires a fresh path" % path
        )
    except OSError as exc:
        raise SinkError("cannot open output %s: %s" % (path, exc))


def _open_sink_for_replay(path, checkpoint):
    if not os.path.exists(path):
        raise CheckpointError(
            "output %s does not exist; cannot recover" % path
        )
    if not os.path.isfile(path):
        raise CheckpointError("output %s is not a regular file" % path)
    try:
        fp = open(path, "r+b")
    except OSError as exc:
        raise SinkError("cannot open output %s: %s" % (path, exc))
    try:
        size = os.fstat(fp.fileno()).st_size
        if size < checkpoint.sink_offset:
            raise CheckpointError(
                "output %s is shorter than the committed checkpoint; "
                "cannot recover" % path
            )
        if size > checkpoint.sink_offset:
            fp.truncate(checkpoint.sink_offset)
            fp.flush()
            os.fsync(fp.fileno())
        fp.seek(0, os.SEEK_END)
    except CheckpointError:
        fp.close()
        raise
    except OSError as exc:
        fp.close()
        raise SinkError("cannot recover output %s: %s" % (path, exc))
    return fp


# --------------------------------------------------------------------------
# Record processing
# --------------------------------------------------------------------------


def _extract_envelope(obj, source_id, line_number):
    where = "source %r line %d" % (source_id, line_number)
    if not isinstance(obj, dict):
        raise DataValidationError("%s: record must be a JSON object" % where)
    for key in ("source_id", "event_id", "payload"):
        if key not in obj:
            raise DataValidationError("%s: record is missing %r" % (where, key))
    if not isinstance(obj["source_id"], str) or obj["source_id"] == "":
        raise DataValidationError("%s: source_id must be a non-empty string" % where)
    event_id = obj["event_id"]
    if event_id is None or isinstance(event_id, (dict, list)):
        raise DataValidationError("%s: event_id must be a scalar" % where)
    if not isinstance(obj["payload"], dict):
        raise DataValidationError("%s: payload must be a JSON object" % where)
    return obj["source_id"], event_id, obj["payload"]


def _write_record(sink, record):
    try:
        sink.write((json.dumps(record, ensure_ascii=False) + "\n").encode(ENCODING))
    except (OSError, TypeError, ValueError) as exc:
        raise SinkError("cannot write output: %s" % exc)


def _flush_sink(sink):
    try:
        sink.flush()
        os.fsync(sink.fileno())
    except OSError as exc:
        raise SinkError("cannot flush output: %s" % exc)


def _count_lines_before(path, offset):
    if offset == 0:
        return 0
    try:
        with open(path, "rb") as fp:
            return sum(1 for _ in fp.read(offset).splitlines())
    except OSError as exc:
        raise SourceError("cannot read %s: %s" % (path, exc))


def _process(config, states, sink, checkpoint_path):
    """Process every source from its current offset; commit per batch."""
    pending = 0

    def commit():
        _flush_sink(sink)
        sink_offset = os.fstat(sink.fileno()).st_size
        Checkpoint(config, states, sink_offset).write_atomic(checkpoint_path)

    counts = {}
    for spec, state in zip(config.sources, states):
        emitted = 0
        try:
            fp = open(spec["path"], "rb")
        except OSError as exc:
            raise SourceError("cannot open input %s: %s" % (spec["path"], exc))
        try:
            size = os.fstat(fp.fileno()).st_size
            if state.offset > size:
                raise CheckpointError(
                    "input %s is shorter than the committed offset; "
                    "cannot recover" % spec["path"]
                )
            fp.seek(state.offset)
            line_number = _count_lines_before(spec["path"], state.offset)
            while True:
                try:
                    raw_line = fp.readline()
                except OSError as exc:
                    raise SourceError("cannot read %s: %s" % (spec["path"], exc))
                if not raw_line:
                    break
                state.offset += len(raw_line)
                line_number += 1
                try:
                    text = raw_line.decode(ENCODING)
                except UnicodeDecodeError:
                    raise DataValidationError(
                        "source %r line %d: malformed JSON"
                        % (spec["id"], line_number)
                    )
                # Every line of a jsonl source is a JSON object; blank or
                # whitespace-only lines are records that fail validation.
                where = "source %r line %d" % (spec["id"], line_number)
                try:
                    obj = json.loads(text)
                except json.JSONDecodeError:
                    raise DataValidationError("%s: malformed JSON" % where)
                source_id, event_id, payload = _extract_envelope(
                    obj, spec["id"], line_number
                )
                if source_id != spec["id"]:
                    raise DataValidationError(
                        "%s: source_id %r does not match configured source"
                        % (where, source_id)
                    )
                data = apply_transforms(payload, config.transforms, where)
                # Source-level transforms run after the shared ones, in
                # their own configured order.
                data = apply_transforms(data, spec["transforms"], where)
                state.note_schema(schema_fingerprint(data))
                record = {
                    "source_id": source_id,
                    "event_id": event_id,
                    "schema_version": state.schema_version,
                    "data": data,
                }
                _write_record(sink, record)
                state.records += 1
                emitted += 1
                pending += 1
                if pending >= spec["batch_size"]:
                    commit()
                    pending = 0
        finally:
            fp.close()
        if pending > 0:
            commit()
            pending = 0
        counts[spec["id"]] = emitted
    # A successful invocation always leaves a checkpoint on disk, even when
    # there was nothing new to append.
    commit()
    return counts


# --------------------------------------------------------------------------
# Public entry points
# --------------------------------------------------------------------------


def run(config, output_path, checkpoint_path):
    """Fresh run: neither output nor checkpoint may exist beforehand."""
    from .errors import ConfigurationError

    _guard_paths(config, output_path, checkpoint_path)
    if os.path.exists(checkpoint_path):
        raise ConfigurationError(
            "checkpoint %s already exists; run requires a fresh path"
            % checkpoint_path
        )
    cp_parent = os.path.dirname(os.path.abspath(checkpoint_path)) or "."
    if not os.path.isdir(cp_parent):
        raise SinkError("checkpoint directory %s does not exist" % cp_parent)
    _ensure_inputs_readable(config)
    states = [SourceState(spec) for spec in config.sources]
    sink = _open_sink_for_run(output_path)
    try:
        return _process(config, states, sink, checkpoint_path)
    finally:
        sink.close()


def replay(config, output_path, checkpoint_path):
    """Resume after the last committed batch, appending without dupes/gaps."""
    _guard_paths(config, output_path, checkpoint_path)
    if not os.path.exists(checkpoint_path):
        raise CheckpointError(
            "checkpoint %s does not exist; replay requires it" % checkpoint_path
        )
    checkpoint = load_checkpoint(checkpoint_path, config)
    _ensure_inputs_readable(config)
    sink = _open_sink_for_replay(output_path, checkpoint)
    try:
        return _process(config, checkpoint.states, sink, checkpoint_path)
    finally:
        sink.close()

"""Minimal block-style YAML parser.

Only the subset needed by stream-etl configuration files is supported:

* block mappings (``key: value``) and block sequences (``- item``)
* nested mappings and sequences (``- key: value``)
* plain scalars (string / integer / number / boolean / null)
* single- and double-quoted strings
* comments (``#``) and blank lines
* a single optional leading ``---`` document marker

Anything outside this subset (flow style, anchors, multiple documents, ...)
raises :class:`YAMLError`. This keeps configuration parsing dependency-free
while still accepting ordinary, hand-written YAML configs.
"""


class YAMLError(ValueError):
    """Raised when input is not YAML in the supported subset."""


class _Line:
    __slots__ = ("indent", "text", "lineno", "col")

    def __init__(self, indent, text, lineno, col=None):
        self.indent = indent
        self.text = text
        self.lineno = lineno
        # column at which text begins in the original source (0-based)
        self.col = indent if col is None else col


def _strip_comment(raw):
    """Remove a trailing comment, respecting quoted strings."""
    out = []
    quote = None
    i = 0
    while i < len(raw):
        ch = raw[i]
        if quote:
            out.append(ch)
            if ch == "\\" and quote == '"' and i + 1 < len(raw):
                out.append(raw[i + 1])
                i += 2
                continue
            if ch == quote:
                quote = None
        else:
            if ch in ("'", '"'):
                quote = ch
                out.append(ch)
            elif ch == "#" and (i == 0 or raw[i - 1] in " \t"):
                break
            else:
                out.append(ch)
        i += 1
    return "".join(out).rstrip()


def _tokenize(text):
    lines = []
    document_open = False
    for lineno, raw in enumerate(text.splitlines(), start=1):
        content = _strip_comment(raw)
        if not content.strip():
            continue
        body = content.lstrip(" \t")
        indent = len(content) - len(body)
        if "\t" in content[:indent]:
            raise YAMLError("tab character in indentation at line %d" % lineno)
        if body == "---":
            if document_open:
                raise YAMLError(
                    "multiple documents are not supported (line %d)" % lineno
                )
            continue
        if body == "...":
            if not document_open:
                continue
            raise YAMLError("unexpected document end marker at line %d" % lineno)
        lines.append(_Line(indent, body, lineno))
        document_open = True
    return lines


def _split_key(text, lineno):
    """Split ``key: value`` on the first colon that ends a key."""
    quote = None
    i = 0
    while i < len(text):
        ch = text[i]
        if quote:
            if ch == quote:
                quote = None
        elif ch in ("'", '"'):
            quote = ch
        elif ch == ":" and (i + 1 == len(text) or text[i + 1] == " "):
            return text[:i], text[i + 1 :].strip()
        i += 1
    raise YAMLError("expected ':' in mapping entry at line %d" % lineno)


def _unquote(token, lineno):
    token = token.strip()
    if len(token) >= 2 and token[0] == token[-1] and token[0] in ("'", '"'):
        quote = token[0]
        body = token[1:-1]
        if quote == "'":
            if "'" in body.replace("''", ""):
                raise YAMLError("invalid single-quoted string at line %d" % lineno)
            return body.replace("''", "'")
        out = []
        i = 0
        escapes = {"n": "\n", "t": "\t", "r": "\r", "\\": "\\", '"': '"', "0": "\0"}
        while i < len(body):
            ch = body[i]
            if ch != "\\":
                out.append(ch)
                i += 1
                continue
            i += 1
            if i >= len(body):
                raise YAMLError("dangling escape in string at line %d" % lineno)
            e = body[i]
            if e == "u" and i + 4 < len(body):
                try:
                    out.append(chr(int(body[i + 1 : i + 5], 16)))
                except ValueError:
                    raise YAMLError("bad unicode escape at line %d" % lineno)
                i += 5
                continue
            if e not in escapes:
                raise YAMLError("unsupported escape \\%s at line %d" % (e, lineno))
            out.append(escapes[e])
            i += 1
        return "".join(out)
    return token


def _parse_scalar(token, lineno):
    token = token.strip()
    if not token:
        return None
    if token[0] in ("'", '"'):
        if len(token) < 2 or token[-1] != token[0]:
            raise YAMLError("unterminated quoted string at line %d" % lineno)
        return _unquote(token, lineno)
    low = token.lower()
    if low in ("null", "~"):
        return None
    if low in ("true", "yes"):
        return True
    if low in ("false", "no"):
        return False
    try:
        return int(token, 10)
    except ValueError:
        pass
    try:
        float(token)
        return float(token)
    except ValueError:
        pass
    if token == "[]":
        return []
    if token == "{}":
        return {}
    if token[0] in "[]{}" or token[0] == "*" or token[0] == "&":
        raise YAMLError(
            "unsupported YAML feature %r at line %d" % (token[:8], lineno)
        )
    return token


def _parse_map(lines, i, indent):
    result = {}
    n = len(lines)
    while i < n:
        ln = lines[i]
        if ln.indent < indent:
            break
        if ln.indent > indent:
            raise YAMLError("unexpected indentation at line %d" % ln.lineno)
        if ln.text == "-" or ln.text.startswith("- "):
            break
        key_tok, val_tok = _split_key(ln.text, ln.lineno)
        key = _unquote(key_tok.strip(), ln.lineno)
        if key == "":
            raise YAMLError("empty mapping key at line %d" % ln.lineno)
        if key in result:
            raise YAMLError("duplicate key %r at line %d" % (key, ln.lineno))
        i += 1
        if val_tok == "":
            if i < n and lines[i].indent > indent:
                value, i = _parse_node(lines, i, lines[i].indent)
            else:
                value = None
        else:
            value = _parse_scalar(val_tok, ln.lineno)
        result[key] = value
    return result, i


def _parse_seq(lines, i, indent):
    result = []
    n = len(lines)
    while i < n:
        ln = lines[i]
        if ln.indent < indent:
            break
        if ln.indent > indent:
            raise YAMLError("unexpected indentation at line %d" % ln.lineno)
        if not (ln.text == "-" or ln.text.startswith("- ")):
            break
        if ln.text == "-":
            i += 1
            if i < n and lines[i].indent > indent:
                value, i = _parse_node(lines, i, lines[i].indent)
            else:
                value = None
            result.append(value)
            continue
        rest = ln.text[2:]
        col = ln.indent + 2
        if _is_map_entry(rest):
            # The rest of the dash line starts a synthetic mapping node at
            # ``col``; following lines belonging to this item align at >= col.
            tail = [_Line(col, rest, ln.lineno, col=col)] + lines[i + 1 :]
            value, consumed = _parse_node(tail, 0, col)
            result.append(value)
            i += consumed
        elif rest == "":
            raise YAMLError("malformed sequence entry at line %d" % ln.lineno)
        else:
            result.append(_parse_scalar(rest, ln.lineno))
            i += 1
    return result, i


def _is_map_entry(text):
    """True if text starts a ``key: value`` mapping entry (respecting quotes)."""
    quote = None
    for idx, ch in enumerate(text):
        if quote:
            if ch == quote:
                quote = None
        elif ch in ("'", '"'):
            quote = ch
        elif ch == ":" and (idx + 1 == len(text) or text[idx + 1] == " "):
            return True
    return False


def _parse_node(lines, i, indent):
    ln = lines[i]
    if ln.indent != indent:
        raise YAMLError("unexpected indentation at line %d" % ln.lineno)
    if ln.text == "-" or ln.text.startswith("- "):
        return _parse_seq(lines, i, indent)
    return _parse_map(lines, i, indent)


def loads(text):
    """Parse a YAML document from a string."""
    if not isinstance(text, str):
        raise YAMLError("YAML input must be text")
    lines = _tokenize(text)
    if not lines:
        return None
    value, i = _parse_node(lines, 0, lines[0].indent)
    if i != len(lines):
        raise YAMLError("unparsed content at line %d" % lines[i].lineno)
    return value


def load(fp):
    """Parse a YAML document from a file-like object."""
    return loads(fp.read())

