# --------------------------------------------------------------------------
# CSV parsing (RFC 4180 subset: comma delimiters, quoted fields, doubled
# quotes, LF/CRLF, embedded newlines, optional leading UTF-8 BOM)
# --------------------------------------------------------------------------


_COMMA = 0x2C
_QUOTE = 0x22
_CR = 0x0D
_LF = 0x0A


class _CSVParser:
    """Byte-oriented parser over one CSV file.

    Structural characters never occur inside UTF-8 continuation bytes, so
    records are located on raw bytes and fields are decoded on demand; this
    keeps the byte offset of every logical record boundary exact.
    """

    def __init__(self, source_id, data, start=0):
        self.sid = source_id
        self.data = data
        self.n = len(data)
        self.pos = start
        # Yielded data records (the header does not count when resuming, as
        # it is part of the committed prefix then).
        self.data_seen = 0
        self.prelude = b""
        if start == 0 and data.startswith(BOM):
            self.pos = len(BOM)
            self.prelude = BOM

    def _label(self):
        if self.pos == 0 or self._at_header:
